const addMediaListener = (media, listener) => {
    if (typeof media?.addEventListener === "function") {
        media.addEventListener("change", listener);
    } else {
        media?.addListener?.(listener);
    }
};

const removeMediaListener = (media, listener) => {
    if (typeof media?.removeEventListener === "function") {
        media.removeEventListener("change", listener);
    } else {
        media?.removeListener?.(listener);
    }
};

const resolveEntries = (root, selector) => {
    let links = [];

    try {
        links = [...root.querySelectorAll(selector)];
    } catch {
        return [];
    }

    return links.map((link) => {
        if (!(link instanceof HTMLAnchorElement) || !link.hash) return null;

        let id = "";
        try {
            id = decodeURIComponent(link.hash.slice(1));
        } catch {
            return null;
        }

        const target = document.getElementById(id);
        return target && target !== root ? { link, target } : null;
    }).filter(Boolean);
};

export default function anchorNav(root, {
    linkSelector = "a[href^='#']",
    activeClass = "active",
} = {}) {
    if (!(root instanceof HTMLElement)) return;

    const entries = resolveEntries(root, linkSelector);
    if (entries.length === 0) return;

    const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)");
    let active = false;
    let frame = 0;
    let resizeObserver = null;
    let activeLink = null;

    const activationLine = () => Math.max(0, root.getBoundingClientRect().bottom);

    const setActive = (nextLink) => {
        if (activeLink === nextLink) return;

        entries.forEach(({ link }) => {
            const isCurrent = link === nextLink;
            link.classList.toggle(activeClass, isCurrent);
            link.parentElement?.classList.toggle(activeClass, isCurrent);
            if (isCurrent) {
                link.setAttribute("aria-current", "location");
            } else {
                link.removeAttribute("aria-current");
            }
        });

        activeLink = nextLink;
    };

    const update = () => {
        frame = 0;
        if (!active) return;

        const line = activationLine();
        let nextEntry = null;
        let bestVisibility = 0;

        entries.forEach((entry) => {
            const box = entry.target.getBoundingClientRect();
            if (box.top <= line && box.bottom > line) {
                nextEntry = entry;
                bestVisibility = Infinity;
                return;
            }

            if (bestVisibility === Infinity) return;
            const visible = Math.max(
                0,
                Math.min(box.bottom, window.innerHeight) - Math.max(box.top, line),
            );
            if (visible > bestVisibility) {
                bestVisibility = visible;
                nextEntry = entry;
            }
        });

        setActive(bestVisibility > 0 || bestVisibility === Infinity ? nextEntry?.link ?? null : null);
    };

    const requestUpdate = () => {
        if (!active || frame) return;
        frame = requestAnimationFrame(update);
    };

    const onClick = (event) => {
        const link = event.target instanceof Element
            ? event.target.closest("a[href^='#']")
            : null;
        const entry = entries.find(({ link: entryLink }) => entryLink === link);
        if (!entry || !root.contains(link)) return;

        event.preventDefault();
        setActive(link);

        const top = Math.max(
            0,
            entry.target.getBoundingClientRect().top + window.scrollY - activationLine(),
        );
        if (typeof window.lenis?.scrollTo === "function") {
            window.lenis.scrollTo(top, {
                duration: reducedMotion.matches ? 0 : 0.8,
                immediate: reducedMotion.matches,
                lock: true,
            });
        } else {
            window.scrollTo({
                top,
                behavior: reducedMotion.matches ? "auto" : "smooth",
            });
        }

        if (window.location.hash !== link.hash) {
            window.history.pushState(null, "", link.hash);
        }
    };

    const start = () => {
        if (active) return;
        active = true;
        root.addEventListener("click", onClick);
        window.addEventListener("scroll", requestUpdate, { passive: true });
        window.addEventListener("resize", requestUpdate, { passive: true });
        window.addEventListener("hashchange", requestUpdate);

        if ("ResizeObserver" in window) {
            resizeObserver = new ResizeObserver(requestUpdate);
            resizeObserver.observe(root);
            entries.forEach(({ target }) => resizeObserver.observe(target));
        }

        update();
    };

    const pause = () => {
        if (!active) return;
        active = false;
        root.removeEventListener("click", onClick);
        window.removeEventListener("scroll", requestUpdate);
        window.removeEventListener("resize", requestUpdate);
        window.removeEventListener("hashchange", requestUpdate);
        resizeObserver?.disconnect();
        resizeObserver = null;
        if (frame) {
            cancelAnimationFrame(frame);
            frame = 0;
        }
    };

    const resume = () => start();
    const onReducedMotionChange = () => requestUpdate();

    addMediaListener(reducedMotion, onReducedMotionChange);
    start();

    return {
        pause,
        resume,
        destroy: () => {
            pause();
            removeMediaListener(reducedMotion, onReducedMotionChange);
            setActive(null);
        },
    };
}
